package craft

import (
	"os"
	"os/exec"
	"path/filepath"
	"testing"
)

// The signer-side script and the daemon must agree on the build-context
// digest byte for byte: a manifest generated by scripts/craft-manifest.sh
// has to pass the daemon's context check.
func TestManifestScriptMatchesDaemonDigest(t *testing.T) {
	for _, tool := range []string{"bash", "sha256sum", "find", "sort", "xargs", "stat"} {
		if _, err := exec.LookPath(tool); err != nil {
			t.Skipf("%s not available", tool)
		}
	}
	repo, err := filepath.Abs("../..")
	if err != nil {
		t.Fatal(err)
	}
	art := t.TempDir()
	if err := os.WriteFile(filepath.Join(art, "wordcraft-1.2.3.tar.gz"), []byte("fake artifact"), 0o644); err != nil {
		t.Fatal(err)
	}
	// A context with nested paths and awkward (but legal) names.
	ctx := t.TempDir()
	for rel, body := range map[string]string{"Dockerfile": "FROM scratch\n", "sub/a b.conf": "x", "sub/Z.conf": "y", "sub/a.conf": "z"} {
		p := filepath.Join(ctx, rel)
		_ = os.MkdirAll(filepath.Dir(p), 0o755)
		if err := os.WriteFile(p, []byte(body), 0o644); err != nil {
			t.Fatal(err)
		}
	}
	for _, context := range []string{ctx, filepath.Join(repo, "images", "craft")} {
		out, err := exec.Command("bash", filepath.Join(repo, "scripts", "craft-manifest.sh"),
			"--counter", "4", "--artifact-dir", art, "--context", context,
			"--app", "wordcraft", "1.2.3", "wordcraft-1.2.3.tar.gz", "--url", "https://example.invalid/w.tar.gz").Output()
		if err != nil {
			t.Fatalf("script: %v", err)
		}
		m, err := ParseManifest(out)
		if err != nil {
			t.Fatalf("script output does not parse: %v\n%s", err, out)
		}
		want, err := TreeDigest(context)
		if err != nil {
			t.Fatal(err)
		}
		if m.ContextDigest != want {
			t.Fatalf("script digest %s != daemon digest %s", m.ContextDigest, want)
		}
		if m.Counter != 4 || m.Apps[0].Artifact.Size != int64(len("fake artifact")) || len(m.Apps[0].Artifact.URLs) != 1 {
			t.Fatalf("manifest = %+v", m)
		}
	}
	// A symlink in the context is refused by the script too.
	if err := os.Symlink("/etc/hostname", filepath.Join(ctx, "link")); err != nil {
		t.Fatal(err)
	}
	if err := exec.Command("bash", filepath.Join(repo, "scripts", "craft-manifest.sh"),
		"--counter", "4", "--artifact-dir", art, "--context", ctx,
		"--app", "wordcraft", "1.2.3", "wordcraft-1.2.3.tar.gz").Run(); err == nil {
		t.Fatal("script accepted a symlink in the context")
	}
}

func TestSignScriptRefusesRepositoryKey(t *testing.T) {
	repo, _ := filepath.Abs("../..")
	m := filepath.Join(t.TempDir(), "m.yaml")
	_ = os.WriteFile(m, []byte("x"), 0o644)
	key := filepath.Join(repo, "images", "craft", "Dockerfile") // any file inside the repo
	out, err := exec.Command("bash", filepath.Join(repo, "scripts", "sign-craft-manifest.sh"), m, "--key", key).CombinedOutput()
	if err == nil {
		t.Fatalf("a key inside the repository was accepted: %s", out)
	}
}
